  let named = null, first = null;
  while (d !== dirname(d)) {
    try {
      const j = JSON.parse(readFileSync(join(d, 'package.json'), 'utf8'));
      first ??= d;
      if (j.name) { named = d; break; }
    } catch { /* missing or unparsable — keep walking */ }
    d = dirname(d);
