// ── css / fonts / tokens ─────────────────────────────────────────────────
// Many DSes ship CSS as a separate import rather than
// importing it from the JS entry. cfg.cssEntry overrides; else the shape
// default; else common dist layouts.
let bundleCssSrcDir = PKG_DIR;
