// React ≤18 ships UMD; React 19 dropped it, so we bundle our own IIFE.
export async function vendorReact({ nodeModules, out }) {
  const reactPkg = JSON.parse(readFileSync(join(nodeModules, 'react/package.json'), 'utf8'));
