    `<h2 style="font:600 16px system-ui;margin:28px 0 10px;color:#374151">${escapeHtml(g)}</h2>\n` +
    `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(460px,1fr));gap:16px">` +
    cs.map((c) =>
